"""Generated by the NL to Flow Diagram Encoder Pipeline."""

string1 = 'This is a Sentence, that needs the chars counted!!'

stringlist = []

for character in string1:
    stringlist.append(character)

countlist = {}

while (len(stringlist) > 0):
    __reserved_keyword__char = stringlist.pop(0)
    if (__reserved_keyword__char not in countlist):
        countlist[__reserved_keyword__char] = 1
    else:
        countlist[__reserved_keyword__char] = (countlist[__reserved_keyword__char] + 1)

for entry in countlist.items():
    key = entry[0]
    val = entry[1]
    print(f'Character {key} appears {val} times')
